def valley_bottom(arr):

  def is_before(i):
    return i == 0 or arr[i] < arr[i - 1]

  l, r = 0, len(arr) - 1
  if is_before(r):
    return arr[r]

  while r - l > 1:
    mid = (l + r) // 2
    if is_before(mid):
      l = mid
    else:
      r = mid
  return arr[l]

