class ValleyBottom {
  public int solve(int[] arr) {
    int l = 0, r = arr.length - 1;
    if (isBefore(r, arr)) {
      return arr[r];
    }

    while (r - l > 1) {
      int mid = (l + r) / 2;
      if (isBefore(mid, arr)) {
        l = mid;
      } else {
        r = mid;
      }
    }
    return arr[l];
  }

  private boolean isBefore(int i, int[] arr) {
    return i == 0 || arr[i] < arr[i - 1];
  }
}

